// Command instagram reads an Instagram account's saved collections through a
// real browser, without storing a password.
//
// It owns no browser itself: every page action is delegated to the
// playwright_browser connector over the wick Host API, so the login lives in
// that plugin's persistent profile. Instagram's web API rejects plain HTTP
// clients (the __dyn/__hs/_js_ claims are generated by the SPA bundle), which is
// why this connector must drive a browser instead of calling /api/graphql with
// net/http.
package main

import (
	wickplugin "github.com/yogasw/wick/pkg/plugin"
)

func main() {
	wickplugin.DeclareHostAccess(
		[]string{wickplugin.ScopeHostConnectorsRead, wickplugin.ScopeHostConnectorsExec},
		&wickplugin.HostResources{
			Connectors: []wickplugin.HostConnectorResource{{
				Connector: "playwright_browser",
				Ops:       []string{"session_open", "session_list", "run", "get_request"},
			}},
		},
	)
	wickplugin.Serve(Module())
}
